DELIMITER $$
CREATE TRIGGER `trg_order_item_prescription_check` BEFORE INSERT ON `order_items` FOR EACH ROW BEGIN
    DECLARE v_requires_rx BOOLEAN;
    DECLARE v_prescription_id INT UNSIGNED;
    DECLARE v_rx_status VARCHAR(30);

    SELECT requires_prescription
      INTO v_requires_rx
    FROM medicines
    WHERE medicine_id = NEW.medicine_id;

    IF v_requires_rx = TRUE THEN
        SELECT prescription_id
          INTO v_prescription_id
        FROM orders
        WHERE order_id = NEW.order_id;

        IF v_prescription_id IS NULL THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Approved prescription is required for this medicine.';
        END IF;

        SELECT status INTO v_rx_status
        FROM prescriptions
        WHERE prescription_id = v_prescription_id;

        IF v_rx_status <> 'APPROVED' THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Prescription must be APPROVED before ordering this medicine.';
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_order_stock_check` BEFORE INSERT ON `order_items` FOR EACH ROW BEGIN
    DECLARE v_pharmacy_id INT UNSIGNED;
    DECLARE v_available INT DEFAULT 0;

    SELECT pharmacy_id INTO v_pharmacy_id
    FROM orders
    WHERE order_id = NEW.order_id;

    SELECT COALESCE(SUM(quantity_on_hand - reserved_quantity),0)
      INTO v_available
    FROM inventory_batches
    WHERE pharmacy_id = v_pharmacy_id
      AND medicine_id = NEW.medicine_id
      AND expiry_date > CURRENT_DATE();

    IF NEW.quantity > v_available THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Insufficient non-expired stock for this order.';
    END IF;
END
$$
DELIMITER ;

