            FROM prescriptions
            WHERE prescription_id = v_prescription_id;

            IF v_rx_status <> 'APPROVED' AND v_res_status <> 'AWAITING_RX' THEN
                SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Prescription is not approved for restricted reservation.';
            END IF;
        END IF;
    END IF;
END
$$
