--
DROP TABLE IF EXISTS `v_expiring_within_90_days`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_expiring_within_90_days`  AS SELECT `ib`.`inventory_batch_id` AS `inventory_batch_id`, `ib`.`pharmacy_id` AS `pharmacy_id`, `m`.`medicine_id` AS `medicine_id`, `m`.`medicine_name` AS `medicine_name`, `ib`.`batch_no` AS `batch_no`, `ib`.`quantity_on_hand` AS `quantity_on_hand`, `ib`.`expiry_date` AS `expiry_date`, to_days(`ib`.`expiry_date`) - to_days(curdate()) AS `days_until_expiry` FROM (`inventory_batches` `ib` join `medicines` `m` on(`m`.`medicine_id` = `ib`.`medicine_id`)) WHERE `ib`.`expiry_date` between curdate() and curdate() + interval 90 day ;

