(1, 91, 81, 'MODERATE', 'Warfarin and Aspirin may increase bleeding risk.', 'Confirm with a healthcare professional before use.', 1),
(2, 91, 14, 'SEVERE', 'Naproxen and Warfarin together greatly increase the risk of bleeding.', 'Pharmacist review required before confirmation.', 1),
(3, 91, 11, 'SEVERE', 'Diclofenac and Warfarin together greatly increase the risk of bleeding.', 'Pharmacist review required before confirmation.', 1),
(4, 91, 17, 'SEVERE', 'Ibuprofen and Warfarin should not be taken together unless advised by a healthcare professional.', 'Pharmacist review required before confirmation.', 1),
(5, 90, 39, 'MODERATE', 'Omeprazole may reduce the antiplatelet effect of Clopidogrel.', 'Consider pantoprazole instead; ask the doctor.', 1),
(6, 134, 135, 'SEVERE', 'Two benzodiazepines together can cause dangerous sedation and breathing problems.', 'Do not combine without doctor approval.', 1),
(7, 138, 19, 'SEVERE', 'Escitalopram with Tramadol increases the risk of serotonin syndrome and seizures.', 'Pharmacist review required before confirmation.', 1),
(8, 85, 82, 'MILD', 'Atenolol with Amlodipine may lower blood pressure more than expected.', 'Monitor blood pressure regularly.', 1),
(9, 147, 11, 'MODERATE', 'Prednisolone with Diclofenac raises the risk of stomach ulcer and bleeding.', 'Take with an acid reducer if prescribed.', 1),
(10, 146, 36, 'CONTRAINDICATED', 'Co-trimoxazole with Methotrexate can cause serious bone marrow suppression.', 'Avoid this combination.', 1);
